sys_script_fix.script:
var gr = new GlideRecord('sys_cs_survey');
gr.addQuery('survey', 'a259f6969f3220100d74d46d842e702a'); //sysID of survey created in Rome. 
gr.query();
while (gr.next()) {
gr.setValue('survey', '45c86b0eeb2330106e6b2ed628522899'); //sysID of updated survey in San Diego.
gr.update();
}
